package com.acme.onboarding;

import java.time.Instant;

public class Customer {
    private String id;
    private String email;
    private String firstName;
    private String lastName;
    private CustomerStatus status;
    private String reviewReason;
    private int riskScore;
    private String kycReference;
    private Instant createdAt;

    public static Customer pending(String email, String firstName, String lastName, Instant createdAt) {
        Customer customer = new Customer();
        customer.email = email;
        customer.firstName = firstName;
        customer.lastName = lastName;
        customer.status = CustomerStatus.PENDING;
        customer.createdAt = createdAt;
        return customer;
    }

    public void markManualReview(int riskScore, String kycReference) {
        this.status = CustomerStatus.MANUAL_REVIEW;
        this.reviewReason = "KYC rejected or risk score above threshold";
        this.riskScore = riskScore;
        this.kycReference = kycReference;
    }

    public void activate(int riskScore, String kycReference) {
        this.status = CustomerStatus.ACTIVE;
        this.riskScore = riskScore;
        this.kycReference = kycReference;
    }

    public String id() { return id; }
    public CustomerStatus status() { return status; }
    public String reviewReason() { return reviewReason; }
}

package com.acme.onboarding;

import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/customers")
public class OnboardingController {
    private final OnboardingService onboardingService;

    public OnboardingController(OnboardingService onboardingService) {
        this.onboardingService = onboardingService;
    }

    @PostMapping("/onboard")
    public ResponseEntity<OnboardingResponse> onboard(@Valid @RequestBody OnboardingRequest request) {
        OnboardingResult result = onboardingService.startOnboarding(request);
        return ResponseEntity.accepted().body(OnboardingResponse.from(result));
    }

    @GetMapping("/{customerId}/status")
    public ResponseEntity<OnboardingStatusResponse> status(@PathVariable String customerId) {
        return ResponseEntity.ok(onboardingService.getStatus(customerId));
    }
}

package com.acme.onboarding;

import java.time.Instant;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OnboardingService {
    private final CustomerRepository customerRepository;
    private final KycClient kycClient;
    private final RiskScoringService riskScoringService;
    private final OnboardingEventPublisher eventPublisher;

    public OnboardingService(CustomerRepository customerRepository, KycClient kycClient,
                             RiskScoringService riskScoringService, OnboardingEventPublisher eventPublisher) {
        this.customerRepository = customerRepository;
        this.kycClient = kycClient;
        this.riskScoringService = riskScoringService;
        this.eventPublisher = eventPublisher;
    }

    @Transactional
    public OnboardingResult startOnboarding(OnboardingRequest request) {
        if (customerRepository.existsByEmail(request.email())) {
            throw new DuplicateCustomerException(request.email());
        }
        KycResult kyc = kycClient.verifyIdentity(request.firstName(), request.lastName(), request.birthDate());
        int riskScore = riskScoringService.calculateScore(request, kyc);
        Customer customer = Customer.pending(request.email(), request.firstName(), request.lastName(), Instant.now());
        if (!kyc.approved() || riskScore > 70) {
            customer.markManualReview(riskScore, kyc.reference());
        } else {
            customer.activate(riskScore, kyc.reference());
        }
        Customer saved = customerRepository.save(customer);
        eventPublisher.publishOnboardingStarted(saved.id(), saved.status());
        return new OnboardingResult(saved.id(), saved.status(), riskScore, kyc.reference());
    }

    public OnboardingStatusResponse getStatus(String customerId) {
        Customer customer = customerRepository.findById(customerId)
            .orElseThrow(() -> new CustomerNotFoundException(customerId));
        return new OnboardingStatusResponse(customer.id(), customer.status(), customer.reviewReason());
    }
}

package com.acme.onboarding;

public class CustomerNotFoundException extends RuntimeException {
    public CustomerNotFoundException(String customerId) {
        super("Customer not found: " + customerId);
    }
}

package com.acme.onboarding;

import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface CustomerRepository extends JpaRepository<Customer, String> {
    boolean existsByEmail(String email);
    Optional<Customer> findById(String customerId);
}

package com.acme.onboarding;

public enum CustomerStatus {
    PENDING,
    ACTIVE,
    MANUAL_REVIEW
}

package com.acme.onboarding;

public class DuplicateCustomerException extends RuntimeException {
    public DuplicateCustomerException(String email) {
        super("Customer already exists: " + email);
    }
}

package com.acme.onboarding;

import java.time.LocalDate;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestTemplate;

@Component
public class KycClient {
    private final RestTemplate restTemplate = new RestTemplate();

    public KycResult verifyIdentity(String firstName, String lastName, LocalDate birthDate) {
        KycRequest request = new KycRequest(firstName, lastName, birthDate);
        return restTemplate.postForObject("https://kyc.example.local/verify", request, KycResult.class);
    }
}

package com.acme.onboarding;

import java.time.LocalDate;

public record KycRequest(String firstName, String lastName, LocalDate birthDate) {}

package com.acme.onboarding;

import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Component;

@Component
public class OnboardingEventPublisher {
    private final KafkaTemplate<String, OnboardingStartedEvent> kafkaTemplate;

    public OnboardingEventPublisher(KafkaTemplate<String, OnboardingStartedEvent> kafkaTemplate) {
        this.kafkaTemplate = kafkaTemplate;
    }

    public void publishOnboardingStarted(String customerId, CustomerStatus status) {
        OnboardingStartedEvent event = new OnboardingStartedEvent(customerId, status.name());
        kafkaTemplate.send("customer.onboarding.started", customerId, event);
    }
}

package com.acme.onboarding;

import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.LocalDate;

public record OnboardingRequest(
    @Email @NotBlank String email,
    @NotBlank String firstName,
    @NotBlank String lastName,
    @NotNull LocalDate birthDate,
    String referralCode
) {}

package com.acme.onboarding;

public record OnboardingResponse(String customerId, CustomerStatus status, int riskScore, String kycReference) {
    public static OnboardingResponse from(OnboardingResult result) {
        return new OnboardingResponse(result.customerId(), result.status(), result.riskScore(), result.kycReference());
    }
}

package com.acme.onboarding;

import org.springframework.stereotype.Service;

@Service
public class RiskScoringService {
    public int calculateScore(OnboardingRequest request, KycResult kyc) {
        int score = 20;
        if (!kyc.approved()) {
            score += 60;
        }
        if (request.referralCode() == null || request.referralCode().isBlank()) {
            score += 15;
        }
        return score;
    }
}

